const monthlyFactor = (frequency) => ({
    "Weekly": 52 / 12,
    "Fortnightly": 26 / 12,
    "Bi-monthly": 2,
    "Monthly": 1
}[frequency] || 1);

const money = (value) => Math.round((Number(value || 0) + Number.EPSILON) * 100) / 100;
let webFinanceSyncing = false;

function webNumberValue(fieldname) {
    const field = frappe.web_form.fields_dict[fieldname];
    const input = field?.wrapper?.querySelector("input");
    const raw = input?.value ?? frappe.web_form.get_value(fieldname) ?? 0;
    return Number(String(raw).replace(/,/g, "")) || 0;
}

function calculateIncomeAndExpenses() {
    const incomeRows = frappe.web_form.get_value("custom_flexi_income_entries") || [];
    const expenseRows = frappe.web_form.get_value("custom_flexi_living_expenses") || [];
    const obligationRows = frappe.web_form.get_value("custom_flexi_finance_obligations") || [];
    const income = incomeRows.reduce((sum, row) => {
        const exact = Number(row.amount || 0) * monthlyFactor(row.frequency);
        row.monthly_amount = money(exact);
        return sum + (row.income_type === "Salary Deductions" ? Math.abs(exact) : exact);
    }, 0);
    const expenses = expenseRows.reduce((sum, row) => {
        const exact = Number(row.expense_amount || 0) * Number(row.frequency_per_month || 1);
        row.monthly_amount = money(exact);
        return sum + exact;
    }, 0);
    const obligations = obligationRows.reduce((sum, row) => {
        const exact = Number(row.amount || 0) * monthlyFactor(row.frequency);
        row.monthly_amount = money(exact);
        return sum + (row.income_type === "Salary Deductions" ? -exact : exact);
    }, 0);
    frappe.web_form.set_value("custom_flexi_total_monthly_income", money(income));
    frappe.web_form.set_value("custom_flexi_total_annual_income", money(income * 12));
    frappe.web_form.set_value("custom_flexi_total_monthly_expenses", money(expenses));
    frappe.web_form.set_value("custom_flexi_net_monthly_income", money(income - expenses));
    frappe.web_form.set_value("custom_flexi_dsr_total_income", money(income));
    frappe.web_form.set_value("custom_flexi_total_finance_obligations", money(obligations));
    frappe.web_form.set_value("custom_flexi_dsr_net_income", money(income - obligations));
    const preDti = income ? money(obligations / income * 100) : 0;
    const maxDsr = Number(frappe.web_form.get_value("custom_flexi_selected_dsr") || 35);
    frappe.web_form.set_value("custom_flexi_pre_dsr", preDti);
    frappe.web_form.set_value("custom_flexi_dsr_margin", money(Math.max(maxDsr - preDti, 0)));
    frappe.web_form.set_value("custom_flexi_weekly_eligibility", money(Math.max((income * maxDsr / 100 - obligations) * 12 / 52, 0)));
    calculateFinanceSummary("amount", { income, obligations });
    renderDtiMatrix(income, obligations);
    renderApplicationReview();
}


function renderDtiMatrix(income, obligations) {
    const field = frappe.web_form.fields_dict.custom_flexi_dti_matrix;
    if (!field?.$wrapper) return;
    const periods = [
        ["Weekly", 12 / 52], ["Fortnightly", 12 / 26],
        ["Bi-Monthly", 1 / 2], ["Monthly", 1]
    ];
    const rows = [
        ["Income Used for DTI", income],
        ["Current Obligations", obligations],
        ["Income After Current Obligations", income - obligations],
        ["Pre-Application DTI", income ? obligations / income * 100 : 0]
    ];
    const head = periods.map(([label]) => `<th>${label}</th>`).join("");
    const body = rows.map(([label, monthly], rowIndex) => {
        const cells = periods.map(([, factor]) => {
            const value = rowIndex === 3 ? monthly : monthly * factor;
            return `<td>${rowIndex === 3 ? money(value).toFixed(2) + "%" : "FJD " + money(value).toLocaleString(undefined, {minimumFractionDigits: 2})}</td>`;
        }).join("");
        return `<tr><th>${label}</th>${cells}</tr>`;
    }).join("");
    field.$wrapper.html(`<div class="flexi-summary-table"><h3>Pre-Application DTI (Debt to Income Ratio)</h3><div class="table-responsive"><table><thead><tr><th>Assessment</th>${head}</tr></thead><tbody>${body}</tbody></table></div></div>`);
}

function renderHirePurchaseTable(values) {
    const section = document.querySelector('[data-fieldname="custom_flexi_terms_section"] .section-body');
    if (!section) return;
    const hiddenFields = [
        "custom_flexi_weekly_instalments", "custom_flexi_weekly_instalment_amount",
        "custom_flexi_fortnightly_instalments", "custom_flexi_fortnightly_instalment_amount",
        "custom_flexi_bimonthly_instalments", "custom_flexi_bimonthly_instalment_amount",
        "custom_flexi_monthly_instalments", "custom_flexi_monthly_instalment_amount"
    ];
    hiddenFields.forEach((fieldname) => {
        const control = section.querySelector(`.frappe-control[data-fieldname="${fieldname}"]`);
        if (control) control.style.display = "none";
    });

    let container = section.querySelector(".flexi-hp-options-table");
    if (!container) {
        container = document.createElement("div");
        container.className = "flexi-hp-options-table flexi-summary-table col-sm-12";
        section.appendChild(container);
    }
    const periods = [
        ["Weekly", "weekly"], ["Fortnightly", "fortnightly"],
        ["Bi-Monthly", "bimonthly"], ["Monthly", "monthly"]
    ];
    const header = periods.map(([label]) => `<th>${label}</th>`).join("");
    const countCells = periods.map(([, key]) =>
        `<td>${values[`custom_flexi_${key}_instalments`] || 0}</td>`
    ).join("");
    const amountCells = periods.map(([, key]) =>
        `<td>FJD ${money(values[`custom_flexi_${key}_instalment_amount`] || 0).toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>`
    ).join("");
    container.innerHTML = `<h3>Hire Purchase Repayment Options</h3>
        <div class="table-responsive"><table>
            <thead><tr><th>Repayment Detail</th>${header}</tr></thead>
            <tbody>
                <tr><th>Number of Instalments</th>${countCells}</tr>
                <tr><th>Instalment Amount</th>${amountCells}</tr>
            </tbody>
        </table></div>`;
}

function calculateFinanceSummary(source = "amount", assessment = {}) {
    if (webFinanceSyncing) return;
    webFinanceSyncing = true;
    try {
        const items = frappe.web_form.get_value("custom_flexi_purchase_items") || [];
        const purchaseValue = items.reduce((sum, row) => {
            const lineTotal = money(Number(row.quantity || 0) * Number(row.unit_price || 0));
            row.total_amount = lineTotal;
            return sum + lineTotal;
        }, 0);
        const surchargeRate = Math.max(webNumberValue("custom_flexi_surcharge_rate"), 0);
        const surchargeAmount = money(purchaseValue * surchargeRate / 100);
        const enteredPercent = webNumberValue("custom_flexi_deposit_percent");
        const enteredAmount = webNumberValue("custom_flexi_deposit_amount");
        // Preserve an amount entered by the applicant. When a percentage is
        // entered, round its resulting deposit upward to the next whole FJD.
        const depositAmount = source === "percent"
            ? Math.min(Math.ceil(Math.max(purchaseValue * enteredPercent / 100, 0)), purchaseValue)
            : Math.min(Math.max(enteredAmount, 0), purchaseValue);
        const depositPercent = source === "percent"
            ? enteredPercent
            : (purchaseValue ? depositAmount / purchaseValue * 100 : 0);
        const afterDeposit = Math.max(purchaseValue - depositAmount, 0) + surchargeAmount;
        const documentationFee = Number(frappe.web_form.get_value("custom_flexi_documentation_fee") || 25);
        const adminFeeRate = Number(frappe.web_form.get_value("custom_flexi_admin_fee_rate") || 2.5);
        const adminFee = afterDeposit * adminFeeRate / 100;
        const stampDuty = Number(frappe.web_form.get_value("custom_flexi_stamp_duty_fee") || 0);
        const otherFee = Number(frappe.web_form.get_value("custom_flexi_other_fee") || 0);
        const financed = purchaseValue ? afterDeposit + documentationFee + adminFee + stampDuty + otherFee : 0;
        const months = Number(frappe.web_form.get_value("custom_flexi_term_months") || 12);
        const interestRate = Number(frappe.web_form.get_value("custom_flexi_interest_rate") || 0);
        const termCharges = financed * interestRate / 100 * months / 12;
        const totalRepayment = financed + termCharges;
        const counts = {
            weekly: Math.round(months * 52 / 12),
            fortnightly: Math.round(months * 26 / 12),
            bimonthly: months * 2,
            monthly: months
        };
        const weeklyAmount = counts.weekly ? totalRepayment / counts.weekly : 0;
        const fortnightlyAmount = counts.fortnightly ? totalRepayment / counts.fortnightly : 0;
        const bimonthlyAmount = counts.bimonthly ? totalRepayment / counts.bimonthly : 0;
        const monthlyAmount = counts.monthly ? totalRepayment / counts.monthly : 0;
        const selectedMonthly = ({
            "Weekly": weeklyAmount * 52 / 12,
            "Fortnightly": fortnightlyAmount * 26 / 12,
            "Bi-monthly": bimonthlyAmount * 2,
            "Monthly": monthlyAmount
        })[frappe.web_form.get_value("custom_flexi_payment_period")] || monthlyAmount;
        const income = assessment.income ?? webNumberValue("custom_flexi_total_monthly_income");
        const obligations = assessment.obligations ?? webNumberValue("custom_flexi_total_finance_obligations");
        const maxDsr = webNumberValue("custom_flexi_selected_dsr") || 35;
        const weeklyEligibility = Math.max((income * maxDsr / 100 - obligations) * 12 / 52, 0);
        const postDsr = income ? (obligations + selectedMonthly) / income * 100 : 0;
        const assessed = income > 0 && totalRepayment > 0;
        const eligible = assessed && weeklyAmount <= weeklyEligibility && postDsr <= maxDsr;
        const values = {
            custom_flexi_cash_price: money(purchaseValue),
            custom_flexi_surcharge_amount: surchargeAmount,
            custom_flexi_full_value: money(purchaseValue + surchargeAmount),
            custom_flexi_deposit_amount: money(depositAmount),
            custom_flexi_deposit_percent: money(depositPercent),
            custom_flexi_value_after_deposit: money(afterDeposit),
            loan_amount: money(financed),
            custom_flexi_documentation_fee: money(documentationFee),
            custom_flexi_admin_fee: money(adminFee),
            custom_flexi_stamp_duty_fee: money(stampDuty),
            custom_flexi_net_amount_financed: money(financed),
            custom_flexi_term_charges: money(termCharges),
            custom_flexi_total_receivable: money(totalRepayment),
            custom_flexi_weekly_instalments: counts.weekly,
            custom_flexi_weekly_instalment_amount: money(weeklyAmount),
            custom_flexi_fortnightly_instalments: counts.fortnightly,
            custom_flexi_fortnightly_instalment_amount: money(fortnightlyAmount),
            custom_flexi_bimonthly_instalments: counts.bimonthly,
            custom_flexi_bimonthly_instalment_amount: money(bimonthlyAmount),
            custom_flexi_monthly_instalments: counts.monthly,
            custom_flexi_monthly_instalment_amount: money(monthlyAmount),
            custom_flexi_post_dsr: money(postDsr),
            custom_flexi_eligibility_status: assessed ? (eligible ? "Achieved" : "Not Achieved") : "Not Assessed",
            repayment_periods: counts.monthly,
            repayment_amount: money(monthlyAmount),
            total_payable_amount: money(totalRepayment),
            total_payable_interest: money(termCharges)
        };
        Object.entries(values).forEach(([fieldname, value]) => {
            if (frappe.web_form.fields_dict[fieldname]) {
                frappe.web_form.set_value(fieldname, value);
            }
        });
        renderHirePurchaseTable(values);
        renderApplicationReview();
    } finally {
        window.setTimeout(() => { webFinanceSyncing = false; }, 100);
    }
}

async function applyLoanProductDefaults() {
    const product =
        frappe.web_form.get_value("loan_product");

    if (!product) return;

    try {
        const response = await frappe.call({
            method: "get_loan_products"
        });

        const products = response.message || [];

        const data = products.find(
            (row) => row.name === product
        );

        if (!data) return;

        if (data.rate_of_interest !== undefined) {
            frappe.web_form.set_value(
                "custom_flexi_interest_rate",
                Number(data.rate_of_interest || 0)
            );
        }

        calculateFinanceSummary();

    } catch (error) {
        console.error(
            "Unable to load Loan Product defaults",
            error
        );
    }
}

async function loadLoanProducts() {
    const field = frappe.web_form.fields_dict.loan_product;
    if (!field) return;

    try {
        const response = await frappe.call({
            method: "get_loan_products"
        });

        const products = response.message || [];

        if (!products.length) {
            console.warn("No Loan Products returned.");
            return;
        }

        const currentValue =
            frappe.web_form.get_value("loan_product") || "";

        field.df.options = [
            "",
            ...products.map(row => row.name)
        ].join("\n");

        field.refresh();

        if (
            currentValue &&
            products.some(row => row.name === currentValue)
        ) {
            frappe.web_form.set_value(
                "loan_product",
                currentValue
            );
        }
    } catch (error) {
        console.error("Loan Product load failed", error);
    }
}

