function calculateApplicantAge() {
    const input = frappe.web_form.fields_dict.custom_flexi_date_of_birth?.wrapper?.querySelector("input");
    const value = input?.value || frappe.web_form.get_value("custom_flexi_date_of_birth");
    if (!value) {
        frappe.web_form.set_value("custom_flexi_age", 0);
        return;
    }
    const parts = String(value).split("-").map(Number);
    if (parts.length !== 3 || parts.some((part) => !Number.isFinite(part))) return;
    const year = parts[0] > 31 ? parts[0] : parts[2];
    if (year < 1900 || year > new Date().getFullYear()) {
        frappe.web_form.set_value("custom_flexi_age", 0);
        return;
    }
    const birth = parts[0] > 31
        ? new Date(parts[0], parts[1] - 1, parts[2])
        : new Date(parts[2], parts[1] - 1, parts[0]);
    if (Number.isNaN(birth.getTime())) return;
    const today = new Date();
    let age = today.getFullYear() - birth.getFullYear();
    if (today.getMonth() < birth.getMonth() ||
        (today.getMonth() === birth.getMonth() && today.getDate() < birth.getDate())) age -= 1;
    frappe.web_form.set_value("custom_flexi_age", Math.max(age, 0));
}

