async function initializeWebForm() {
    frappe.defaults = frappe.defaults || {};
    frappe.defaults.get_user_default = frappe.defaults.get_user_default || (() => null);
    frappe.defaults.get_global_default = frappe.defaults.get_global_default || (() => null);
    frappe.sys_defaults = frappe.sys_defaults || {};
    frappe.sys_defaults.country = "Fiji";
    setWebFormPhoneCountryDefaults();
    makeCalculatedFieldsReadOnly();
    // Website pages do not always receive the Desk system defaults, causing
    // Frappe's Phone control to fall back to India (+91). Keep this Web Form
    // and any Phone controls opened later in child-table rows on Fiji (+679).
    frappe.sys_defaults = frappe.sys_defaults || {};
    frappe.sys_defaults.country = "Fiji";
    setWebFormPhoneCountryDefaults();
    if (!frappe.web_form.get_value("posting_date")) {
        frappe.web_form.set_value("posting_date", frappe.datetime.get_today());
    }
    seedTableRows("custom_flexi_application_contacts", defaultContactRows);
    seedTableRows("custom_flexi_income_entries", defaultIncomeRows);
    seedTableRows("custom_flexi_finance_obligations", defaultObligationRows);
    seedTableRows("documents", defaultDocumentRows);
    configureTablePhoneFields();
    refreshAddressDropdowns();
    syncStandardAddressFields();
    seedTableRows(
        "custom_flexi_living_expenses",
        defaultLivingExpenseRows
    );
    calculateIncomeAndExpenses();
    calculateApplicantAge();
    applyLoanProductDefaults();
    markSubmitRequiredFields();
    updateSpouseRequirements();
    bindTableCalculations();
    bindPurchaseItemCalculations();
    bindDepositCalculations();
    bindSimpleSeededTableInputs();
    bindApplicantDateCalculation();
    bindSubmitValidation();
    bindClickableSteps();
    loadLoanProducts();
}

