        ...row,
        idx: index + 1,
        __islocal: true
    }));
    field.grid.refresh();
    frappe.web_form.make_form_dirty();
}

function seedTableRows(fieldname, rows) {
    const existing = frappe.web_form.get_value(fieldname) || [];
    const hasEnteredData = existing.some((row) => {
        if (fieldname === "custom_flexi_income_entries") return Number(row.amount || 0) > 0;
        if (fieldname === "custom_flexi_living_expenses") return Number(row.expense_amount || 0) > 0;
        if (fieldname === "custom_flexi_finance_obligations") return Number(row.amount || 0) > 0;
        if (fieldname === "custom_flexi_application_contacts") return Boolean(String(row.full_name || "").trim());
        if (fieldname === "documents") return Boolean(String(row.file || "").trim());
        return false;
    });
    if (!hasEnteredData) setTableRows(fieldname, rows);
}

function bindClickableSteps() {
    const footer = $(".web-form-footer");
    footer.off("click.flexiSteps keydown.flexiSteps", ".slide-step");
    footer.on("click.flexiSteps keydown.flexiSteps", ".slide-step", function(event) {
        if (event.type === "keydown" && !["Enter", " "].includes(event.key)) return;
        event.preventDefault();
        const target = Number($(this).attr("data-step-id"));
        if (!Number.isInteger(target) || target < 0 || target > frappe.web_form.page_breaks.length) return;
        frappe.web_form.current_section = target;
        frappe.web_form.toggle_section();
        window.scrollTo({ top: Math.max($(".web-form-container").offset().top - 20, 0), behavior: "smooth" });
    });
    $(".slide-step").attr({ role: "button", tabindex: "0" });
}




function bindDepositCalculations() {
    const configurations = {
        custom_flexi_deposit_amount: "amount",
        custom_flexi_deposit_percent: "percent"
    };
    Object.entries(configurations).forEach(([fieldname, source]) => {
        const field = frappe.web_form.fields_dict[fieldname];
        if (!field?.wrapper || field.wrapper.dataset.flexiDepositBound) return;
        field.wrapper.dataset.flexiDepositBound = "1";
        let timer;
        // Do not calculate on every keystroke: formatting during entry turns
        // the first digit into e.g. 5.000 and prevents typing the remaining digits.
        $(field.wrapper).on("change.flexiDeposit focusout.flexiDeposit", "input", () => {
            if (webFinanceSyncing) return;
            window.clearTimeout(timer);
            timer = window.setTimeout(() => {
                if (!webFinanceSyncing) calculateFinanceSummary(source);
            }, 0);
        });
    });
}


