function bindSimpleSeededTableInputs() {
    const configurations = {
        custom_flexi_application_contacts: [
            "contact_type", "full_name", "relationship", "mobile_number", "home_phone",
            "lot_number", "province", "city", "suburb", "district", "street",
            "employer", "occupation", "employment_period", "employer_address", "employer_contact"
        ]
    };
    Object.entries(configurations).forEach(([fieldname, columns]) => {
        const field = frappe.web_form.fields_dict[fieldname];
        if (!field?.grid || field.wrapper.dataset.flexiSeededTableBound) return;
        field.wrapper.dataset.flexiSeededTableBound = "1";
        $(field.wrapper).on("input.flexiSeededTable change.flexiSeededTable", "input, select, textarea", (event) => {
            const columnName = event.target.dataset.fieldname;
            if (!columns.includes(columnName)) return;
            const rowIndex = Number(event.target.closest(".grid-row")?.dataset.idx) - 1;
            const row = field.df.data?.[rowIndex];
            if (row) row[columnName] = event.target.value;
        });
    });
