function bindPurchaseItemCalculations() {
    const field = frappe.web_form.fields_dict.custom_flexi_purchase_items;
    if (!field?.grid || field.wrapper.dataset.flexiPurchaseBound) return;
    field.wrapper.dataset.flexiPurchaseBound = "1";
    ["quantity", "unit_price"].forEach((columnName) => {
        const df = field.grid.docfields.find((item) => item.fieldname === columnName);
        if (!df) return;
        const existingOnChange = df.onchange;
        df.onchange = function(event) {
            if (existingOnChange) existingOnChange.call(this, event);
            window.setTimeout(calculateFinanceSummary, 0);
        };
    });
    field.grid.refresh();
    let purchaseTimer;
    $(field.wrapper).on("input.flexiPurchase change.flexiPurchase", "input", (event) => {
        const columnName = event.target.dataset.fieldname;
        if (!["product_description", "quantity", "unit_price"].includes(columnName)) return;
        const rowElement = event.target.closest(".grid-row");
        const rowIndex = Number(rowElement?.dataset.idx) - 1;
        const row = field.df.data?.[rowIndex];
        if (row) {
            row[columnName] = columnName === "product_description"
                ? event.target.value
                : Number(event.target.value || 0);
            row.total_amount = money(Number(row.quantity || 0) * Number(row.unit_price || 0));
            if (row.doctype && row.name) {
                frappe.model.set_value(row.doctype, row.name, "total_amount", row.total_amount);
            }
        }
        window.clearTimeout(purchaseTimer);
        purchaseTimer = window.setTimeout(() => {
            const totalInput = rowElement?.querySelector('input[data-fieldname="total_amount"]');
            if (totalInput && row) totalInput.value = money(row.total_amount).toFixed(2);
            calculateFinanceSummary();
        }, 350);
    });
}

