function isBlankForSubmission(fieldname, value) {
    if (fieldname === "custom_cira_authority_acknowledged") return !Number(value);
    if (fieldname === "custom_flexi_purchase_items") {
        return !Array.isArray(value) || !value.some((row) =>
            String(row.product_description || "").trim() &&
            Number(row.quantity || 0) > 0 && Number(row.unit_price || 0) > 0
        );
    }
    if (fieldname === "applicant_phone_number") {
        const digits = String(value || "").replace(/\D/g, "");
        return digits === "679" || digits.length < 10;
    }
    if (fieldname === "custom_flexi_living_expenses") {
        return !Array.isArray(value) || !value.some((row) => Number(row.expense_amount || 0) > 0);
    }
    if (fieldname === "custom_flexi_income_entries") {
        return !Array.isArray(value) || !value.some((row) => Number(row.amount || 0) > 0);
    }
    if (fieldname === "custom_flexi_application_contacts") {
        return !Array.isArray(value) || !value.some((row) => String(row.full_name || "").trim());
    }
    if (Array.isArray(value)) return value.length === 0;
    return value === undefined || value === null || value === "";
}

function syncApplicantName() {
