    if (fullName && frappe.web_form.get_value("custom_cira_authority_name") !== fullName) {
        frappe.web_form.set_value("custom_cira_authority_name", fullName);
        frappe.web_form.fields_dict.custom_cira_authority_name?.refresh();
    }
}

function normalizeFijiPhone(value) {
    let digits = String(value || "").replace(/\D/g, "");
    while (digits.startsWith("679679")) digits = digits.slice(3);
    if (digits.startsWith("679") && digits.length === 10) digits = digits.slice(3);
    if (digits.length === 7) return `+679 ${digits}`;
    return String(value || "").trim();
}

function normalizeFijiPhoneFields() {
    [
        "applicant_phone_number",
        "custom_flexi_employer_contact",
        "custom_flexi_spouse_mobile",
        "custom_flexi_spouse_employer_contact"
    ].forEach((fieldname) => {
        const current = frappe.web_form.get_value(fieldname);
        if (!current) return;
        const normalized = normalizeFijiPhone(current);
        if (normalized !== current) frappe.web_form.set_value(fieldname, normalized);
    });
    const contacts = frappe.web_form.get_value("custom_flexi_application_contacts") || [];
    contacts.forEach((row) => {
        ["mobile_number", "home_phone", "employer_contact"].forEach((fieldname) => {
            if (row[fieldname]) row[fieldname] = normalizeFijiPhone(row[fieldname]);
        });
    });
}

function bindSubmitValidation() {
    const button = document.querySelector(".submit-btn");
    if (!button || button.dataset.finalValidationBound) return;
    button.dataset.finalValidationBound = "1";
    button.addEventListener("click", async (event) => {
        if (button.dataset.finalSubmitReady) {
            delete button.dataset.finalSubmitReady;
            return;
        }
        normalizeFijiPhoneFields();
        syncStandardAddressFields();
        const missing = submitRequiredFields.filter(([fieldname]) =>
            isBlankForSubmission(fieldname, frappe.web_form.get_value(fieldname))
        );
        const applicantAge = Number(frappe.web_form.get_value("custom_flexi_age") || 0);
        if (frappe.web_form.get_value("custom_flexi_date_of_birth") && applicantAge < 18) {
            missing.push(["custom_flexi_age", "Applicant must be at least 18 years old"]);
        }
        if (frappe.web_form.get_value("custom_flexi_marital_status") === "Married" &&
            isBlankForSubmission("custom_flexi_spouse_email", frappe.web_form.get_value("custom_flexi_spouse_email"))) {
            missing.push(["custom_flexi_spouse_email", "Spouse Email Address"]);
        }
        if (missing.length) {
            event.preventDefault();
            event.stopImmediatePropagation();
            const items = missing.map(([, label]) => `<li>${frappe.utils.escape_html(label)}</li>`).join("");
            frappe.msgprint({
                title: __("Please complete the application"),
                message: `<p>Before submitting, complete these required fields:</p><ul>${items}</ul>`,
                indicator: "orange"
            });
            return;
        }

        const contacts = frappe.web_form.get_value("custom_flexi_application_contacts") || [];
        const incomeRows = frappe.web_form.get_value("custom_flexi_income_entries") || [];
        const expenseRows = frappe.web_form.get_value("custom_flexi_living_expenses") || [];
        const obligationRows = frappe.web_form.get_value("custom_flexi_finance_obligations") || [];
        const documentRows = frappe.web_form.get_value("documents") || [];
        const completedContacts = contacts.filter((row) => String(row.full_name || "").trim());
        const completedIncome = incomeRows.filter((row) => Number(row.amount || 0) > 0);
        const completedExpenses = expenseRows.filter((row) => Number(row.expense_amount || 0) > 0);
        const completedObligations = obligationRows.filter((row) => Number(row.amount || 0) > 0);
        const completedDocuments = documentRows.filter((row) => String(row.file || "").trim());
        const needsCleanup = completedContacts.length !== contacts.length ||
            completedIncome.length !== incomeRows.length ||
            completedExpenses.length !== expenseRows.length ||
            completedObligations.length !== obligationRows.length ||
            completedDocuments.length !== documentRows.length;
        if (needsCleanup) {
            event.preventDefault();
            event.stopImmediatePropagation();
            setTableRows("custom_flexi_application_contacts", completedContacts);
            setTableRows("custom_flexi_income_entries", completedIncome);
            setTableRows("custom_flexi_living_expenses", completedExpenses);
            setTableRows("custom_flexi_finance_obligations", completedObligations);
            setTableRows("documents", completedDocuments);
            calculateIncomeAndExpenses();
            button.dataset.finalSubmitReady = "1";
            button.click();
        }
    }, true);
}

