		}
		if (incomeTables.has(table)) return queue("income");
		if (!financeFields.has(fieldname)) return;
		if (fieldname === "custom_flexi_deposit_percent") depositSource = "percent";
		if (fieldname === "custom_flexi_deposit_amount") depositSource = "amount";
		queue("finance");
	}

	document.addEventListener("input", onChanged, true);
	document.addEventListener("change", onChanged, true);
})();

/* comfort_homes: loan application live calculation refresh v3 */
(function () {
	let refreshTimer;
	let depositSource;
	const purchaseTable = "custom_flexi_purchase_items";
	const incomeTables = new Set([
		"custom_flexi_income_entries", "custom_flexi_living_expenses", "custom_flexi_finance_obligations"
	]);
	const financeFields = new Set([
		"custom_flexi_deposit_amount", "custom_flexi_deposit_percent", "custom_flexi_surcharge_rate",
		"custom_flexi_documentation_fee", "custom_flexi_admin_fee_rate", "custom_flexi_stamp_duty_fee",
		"custom_flexi_other_fee", "custom_flexi_term_months", "custom_flexi_interest_rate",
		"custom_flexi_payment_period", "custom_flexi_selected_dsr", "loan_product"
	]);
	const number = (value) => Number(String(value ?? 0).replace(/,/g, "")) || 0;
	const money = (value) => Math.round((number(value) + Number.EPSILON) * 100) / 100;

	function tableFor(target) {
		return [purchaseTable, ...incomeTables].find((fieldname) =>
			target?.closest?.(`[data-fieldname="${fieldname}"]`)
		);
	}

	function setChildValue(row, fieldname, value) {
		if (money(row[fieldname]) === money(value)) return;
		row[fieldname] = value;
		if (row.doctype && row.name) frappe.model.set_value(row.doctype, row.name, fieldname, value);
	}

	function sourceForDeposit() {
		if (depositSource) return depositSource;
		const amount = number(frappe.web_form.get_value("custom_flexi_deposit_amount"));
		const percent = number(frappe.web_form.get_value("custom_flexi_deposit_percent"));
		return !amount && percent ? "percent" : "amount";
	}

	function recalculate(kind) {
		if (!frappe.web_form) return;
		if (kind === "income") {
			calculateIncomeAndExpenses();
			return;
		}
		if (kind === "purchase") {
			const rows = frappe.web_form.get_value(purchaseTable) || [];
			const purchaseValue = rows.reduce((total, row) => {
				const lineTotal = money(number(row.quantity) * number(row.unit_price));
				setChildValue(row, "total_amount", lineTotal);
				return total + lineTotal;
			}, 0);
			frappe.web_form.set_value("custom_flexi_cash_price", money(purchaseValue));
			frappe.web_form.fields_dict[purchaseTable]?.refresh?.();
		}
		calculateFinanceSummary(sourceForDeposit());
	}

	function queue(kind) {
		window.clearTimeout(refreshTimer);
		// Grid controls finish updating their row a little after the browser event.
		refreshTimer = window.setTimeout(() => recalculate(kind), 450);
	}

	function onChanged(event) {
		const fieldname = event.target?.closest?.("[data-fieldname]")?.dataset?.fieldname;
		const table = tableFor(event.target);
		if (table === purchaseTable) {
			// Remember the initial 10% (or other configured) deposit before the
			// older table listener has a chance to reset it to zero on an empty row.
			depositSource = depositSource || sourceForDeposit();
			return queue("purchase");
		}
		if (incomeTables.has(table)) return queue("income");
		if (!financeFields.has(fieldname)) return;
		if (fieldname === "custom_flexi_deposit_percent") depositSource = "percent";
		if (fieldname === "custom_flexi_deposit_amount") depositSource = "amount";
		queue("finance");
	}

	document.addEventListener("input", onChanged, true);
	document.addEventListener("change", onChanged, true);
	// Preserve a configured default percentage (for example 10%) before a
	// newly-added blank item row causes the legacy table listener to reset it.
	window.setTimeout(() => {
		if (!depositSource) depositSource = sourceForDeposit();
	}, 0);
})();

/* comfort_homes: loan application employment period */
(function () {
	function updateEmploymentPeriod() {
		const startDate = frappe.web_form.get_value("custom_flexi_employment_start_date");
		if (!startDate) {
			frappe.web_form.set_value("custom_flexi_employment_period", "");
			return;
		}
		const start = new Date(`${startDate}T00:00:00`);
		const now = new Date();
		if (Number.isNaN(start.getTime()) || start > now) return;
		let months = (now.getFullYear() - start.getFullYear()) * 12 + now.getMonth() - start.getMonth();
		if (now.getDate() < start.getDate()) months -= 1;
		months = Math.max(months, 0);
		const years = Math.floor(months / 12);
		const remainder = months % 12;
		const period = `${years} ${years === 1 ? "year" : "years"}${remainder ? ` ${remainder} ${remainder === 1 ? "month" : "months"}` : ""}`;
		frappe.web_form.set_value("custom_flexi_employment_period", period);
	}

	frappe.web_form.on("custom_flexi_employment_start_date", updateEmploymentPeriod);
	frappe.web_form.events.on("after_load", updateEmploymentPeriod);
})();

custom_css:
body {
    background: #f5f7fb;
    color: #243247;
    font-size: 14px;
}
main.container {
    width: 100% !important;
    max-width: none !important;
    margin: 0 !important;
    padding-right: 24px !important;
    padding-left: 24px !important;
}
.page_content {
    width: 100% !important;
    max-width: none !important;
}
.web-form-container {
    width: min(1440px, 100%);
    max-width: none;
    margin: 36px auto 64px;
    padding: 30px 36px;
    border: 1px solid #e4e9f0;
    border-radius: 18px;
    background: #fff;
    box-shadow: 0 14px 40px rgba(31, 52, 80, 0.08);
}
.web-form-container h1 {
    color: #17243a;
    font-size: clamp(26px, 3.4vw, 36px);
    letter-spacing: -0.02em;
}
.web-form-container .web-form-introduction,
.web-form-container .introduction {
    margin: 20px 0 28px;
    padding: 16px 18px;
    border: 1px solid #cfe4f7;
    border-radius: 12px;
    background: #f1f8ff;
    color: #3b526d;
    line-height: 1.65;
}
.web-form .form-section {
    margin: 0 0 18px;
    padding: 18px 20px 20px;
    border: 1px solid #e7ebf1;
    border-radius: 14px;
    background: #fff;
}
.web-form .section-head {
    margin: 0 0 18px !important;
    padding: 0 0 11px;
    border-bottom: 1px solid #edf0f4;
    color: #1d3557;
    font-size: 18px;
    font-weight: 700;
}
.web-form .control-label {
    margin-bottom: 7px;
    color: #34445b;
    font-size: 14px;
    font-weight: 600;
}
.web-form .flexi-submit-required > .form-group .control-label::after,
.web-form .flexi-submit-required > .form-group > .clearfix .control-label::after,
.web-form .flexi-submit-required .grid-heading-row::after {
    content: " *";
    color: #d64545;
    font-weight: 700;
}
.web-form .flexi-submit-required .grid-heading-row::after {
    display: inline-block;
    margin: 7px 0 0 10px;
}
.web-form input.form-control,
.web-form select.form-control,
.web-form .select2-selection,
.web-form .awesomplete > input,
.web-form textarea.form-control {
    min-height: 42px;
    border: 1px solid #d6dde7 !important;
    border-radius: 9px !important;
    background: #fbfcfe !important;
    box-shadow: none !important;
    font-size: 15px;
}
.web-form textarea.form-control { min-height: 120px; padding-top: 11px; }
.web-form input.form-control:focus,
.web-form textarea.form-control:focus,
.web-form .select2-container--focus .select2-selection {
    border-color: #3276d2 !important;
    background: #fff !important;
    box-shadow: 0 0 0 3px rgba(50, 118, 210, 0.12) !important;
}
.web-form .help-box,
.web-form .description {
    margin-top: 7px;
    color: #718096 !important;
    font-size: 12px;
    line-height: 1.45;
}
.web-form .grid-heading-row {
    background: #f3f6fa;
    color: #4a5b72;
    font-weight: 600;
}
.web-form .form-grid {
    width: 100%;
    overflow: hidden;
    border: 1px solid #dfe5ed;
    border-radius: 11px;
}
.web-form .grid-body { min-height: 66px; }
.web-form .grid-static-col,
.web-form .grid-row .data-row > .row > div {
    min-width: 110px;
}
.web-form .grid-row .data-row > .row > div:first-child,
.web-form .grid-heading-row .row > div:first-child { min-width: 38px; }
.web-form .btn-open-row,
.web-form .grid-add-row,
.web-form .btn-add-row {
    min-height: 38px;
    border-radius: 9px;
    font-weight: 600;
}
.web-form-footer {
    position: static;
    width: 100%;
    transform: none;
    z-index: 10;
    margin-top: 26px;
    padding: 16px 18px;
    border: 1px solid #dfe5ed;
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.96);
    box-shadow: 0 10px 28px rgba(31, 52, 80, 0.12);
    backdrop-filter: blur(8px);
}
.web-form-footer .btn {
    min-height: 40px;
    padding: 9px 18px;
    border-radius: 10px;
    font-size: 14px;
    font-weight: 700;
}
.web-form-footer .btn-next,
.web-form-footer .submit-btn {
    border-color: #1769c2 !important;
    background: #1769c2 !important;
    color: #fff !important;
}
.web-form-footer .btn-next:hover,
.web-form-footer .submit-btn:hover { background: #10589f !important; }
.web-form-footer .discard-btn { color: #68768a; }
.web-form-actions {
    display: grid !important;
    grid-template-columns: 1fr auto;
    align-items: start;
    row-gap: 28px;
    padding-bottom: 18px;
}
.web-form-actions .left-area { grid-column: 1; grid-row: 2; justify-self: start; }
.web-form-actions .right-area { grid-column: 2; grid-row: 2; justify-self: end; white-space: nowrap; }
.web-form-actions .center-area.paging {
    grid-column: 1 / -1;
    grid-row: 1;
    justify-self: center;
    width: min(520px, 100%) !important;
}
.slides-progress {
    display: grid !important;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    width: 100%;
}
.slide-step {
    position: relative;
    width: auto !important;
    min-height: 42px;
    padding: 0 8px;
    border: 1px solid #d8e0e9;
    border-radius: 10px;
    background: #f3f6fa;
    text-align: center;
    cursor: pointer;
    transition: border-color 0.18s ease, background-color 0.18s ease, transform 0.18s ease;
}
.slide-step:hover { border-color: #8db5df; transform: translateY(-1px); }
.slide-step .slide-step-indicator,
.slide-step .slide-step-complete { display: none !important; }
.slide-step::after {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: calc(100% - 12px);
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 500;
    line-height: 1.2;
    white-space: normal;
}
.slide-step:nth-child(1)::after { content: "Applicant Details"; }
.slide-step:nth-child(2)::after { content: "Income & Expenses"; }
.slide-step:nth-child(3)::after { content: "DTI & Loan Details"; }
.slide-step:nth-child(4)::after { content: "Upload & Submit"; }
.slide-step.active {
    border-color: #1769c2 !important;
    background: #1769c2 !important;
}
.slide-step.active::after { color: #fff; font-weight: 700; }
.slide-step.step-success {
    border-color: #b8d7c4 !important;
    background: #edf8f1 !important;
}
.slide-step.step-success::after { color: #276749; }
.web-form [data-fieldname="custom_flexi_living_expenses"],
.web-form [data-fieldname="custom_flexi_income_entries"] { max-width: none !important; }
@media (max-width: 700px) {
    main.container { padding-right: 8px !important; padding-left: 8px !important; }
    .web-form-container {
        width: 100%;
        margin: 12px 0 36px;
        padding: 22px 14px;
        border-radius: 14px;
    }
    .web-form .form-section { padding: 18px 14px 20px; }
    .web-form .form-grid { overflow-x: auto; }
    .web-form-footer {
        width: 100%;
        padding: 12px;
    }
    .web-form-actions { row-gap: 34px; }
    .web-form-actions .center-area.paging {
        grid-column: 1 / -1;
        grid-row: 1;
        min-width: 0;
    }
    .web-form-actions .left-area { grid-column: 1; grid-row: 2; }
    .web-form-actions .right-area { grid-column: 2; grid-row: 2; }
    .slides-progress { gap: 6px; }
    .slide-step { min-height: 48px; padding: 0 4px; }
    .slide-step::after { width: calc(100% - 6px); font-size: 10px; }
    .web-form-footer .btn { min-height: 42px; padding: 8px 12px; }
}

.flexi-summary-table { margin: 6px 0 20px; }
.flexi-summary-table h3 { margin: 0 0 14px; color: #1d3557; font-size: 18px; }
.flexi-summary-table table { width: 100%; border-collapse: separate; border-spacing: 0; overflow: hidden; border: 1px solid #dfe5ed; border-radius: 11px; }
.flexi-summary-table th, .flexi-summary-table td { padding: 11px 13px; border-right: 1px solid #e8edf3; border-bottom: 1px solid #e8edf3; text-align: right; }
.flexi-summary-table th:first-child { text-align: left; }
.flexi-summary-table thead th { background: #edf4fb; color: #294866; }
.flexi-summary-table tbody th { background: #f8fafc; color: #43556b; }
.flexi-review-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.flexi-review-grid > div { padding: 14px 16px; border: 1px solid #dfe5ed; border-radius: 10px; background: #f8fafc; }
.flexi-review-grid span, .flexi-review-grid strong { display: block; }
.flexi-review-grid span { margin-bottom: 5px; color: #718096; font-size: 12px; }
@media (max-width: 700px) {
    .flexi-summary-table .table-responsive { overflow-x: auto; }
    .flexi-summary-table table { min-width: 680px; }
    .flexi-review-grid { grid-template-columns: 1fr; }
}
